import{_ as t,o as i,c as n,ah as a}from"./chunks/framework.D4KxWb5R.js";const p=JSON.parse(`{"title":"Intégration technique : vue d'ensemble","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integration/overview.md","filePath":"src/guide/integration/overview.md"}`),r={name:"guide/integration/overview.md"};function d(o,e,s,c,u,l){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="integration-technique-vue-d-ensemble" tabindex="-1">Intégration technique : vue d&#39;ensemble <a class="header-anchor" href="#integration-technique-vue-d-ensemble" aria-label="Permalink to &quot;Intégration technique : vue d&#39;ensemble&quot;">​</a></h1><p>Cette partie s&#39;adresse aux équipes techniques des produits qui raccordent leur back-office à M&#39;City IQ. Elle décrit le contrat complet ; Auticway en est la première implémentation.</p><h2 id="les-quatre-liens" tabindex="-1">Les quatre liens <a class="header-anchor" href="#les-quatre-liens" aria-label="Permalink to &quot;Les quatre liens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lien</th><th>Sens</th><th>Rôle</th></tr></thead><tbody><tr><td><a href="./sso.html">SSO (OpenID Connect)</a></td><td>Produit → M&#39;City</td><td>Le personnel M&#39;City se connecte au back-office avec son compte M&#39;City.</td></tr><tr><td><a href="./api.html">API</a></td><td>Produit → M&#39;City</td><td>Le produit lit sa fiche et met à jour son URL d&#39;accès et ses langues.</td></tr><tr><td><a href="./webhook.html">Webhook</a></td><td>M&#39;City → produit</td><td>M&#39;City pousse la fiche produit à chaque modification.</td></tr><tr><td><a href="./indicators.html">Indicateurs</a></td><td>Produit → M&#39;City</td><td>Le produit remonte ses indicateurs consolidés, par envoi ou par relevé.</td></tr></tbody></table><p>M&#39;City IQ ne reçoit que des valeurs agrégées, jamais de données personnelles des utilisateurs du produit.</p><h2 id="environnements" tabindex="-1">Environnements <a class="header-anchor" href="#environnements" aria-label="Permalink to &quot;Environnements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Environnement</th><th>Émetteur OIDC</th><th>Base de l&#39;API</th></tr></thead><tbody><tr><td>Production</td><td><code>https://mcityiq.com</code></td><td><code>https://mcityiq.com/api/v1</code></td></tr><tr><td>Test</td><td><code>https://mcity.edpage.net</code></td><td><code>https://mcity.edpage.net/api/v1</code></td></tr></tbody></table><p>Les identifiants de l&#39;un ne fonctionnent pas sur l&#39;autre.</p><h2 id="ce-que-le-pdg-vous-transmet" tabindex="-1">Ce que le PDG vous transmet <a class="header-anchor" href="#ce-que-le-pdg-vous-transmet" aria-label="Permalink to &quot;Ce que le PDG vous transmet&quot;">​</a></h2><p>Le PDG de M&#39;City configure le produit dans le registre (voir <a href="./../administration/registry.html#integration-d-un-produit">Intégration d&#39;un produit</a>) :</p><table tabindex="0"><thead><tr><th>Élément</th><th>Où il est créé</th><th>Ce que vous fournissez</th></tr></thead><tbody><tr><td>Identifiant et secret du client OIDC</td><td>Intégration SSO</td><td>Les URI de redirection (HTTPS, 5 au plus) et, si besoin, l&#39;URI de déconnexion back-channel</td></tr><tr><td>Jeton de service <code>mcity_…</code></td><td>Intégration API</td><td>—</td></tr><tr><td>Secret de webhook</td><td>Intégration API</td><td>L&#39;URL du webhook et l&#39;URL du back-office (pour le relevé)</td></tr><tr><td>Identifiant du produit (UUID)</td><td>Fiche produit</td><td>—</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Secrets</p><p>Chaque secret n&#39;est affiché qu&#39;une fois, puis stocké haché ou chiffré. Il doit vous parvenir par un canal sûr (gestionnaire de mots de passe partagé, par exemple), jamais par e-mail en clair ni dans un ticket. En régénérer un révoque l&#39;ancien : prévoyez la mise à jour de votre configuration au même moment.</p></div><h2 id="conventions-communes" tabindex="-1">Conventions communes <a class="header-anchor" href="#conventions-communes" aria-label="Permalink to &quot;Conventions communes&quot;">​</a></h2><ul><li>JSON, champs en <code>camelCase</code>, identifiants UUID, dates ISO 8601 en UTC.</li><li>Les appels de M&#39;City vers le produit sont signés par HMAC (voir <a href="./webhook.html#verifier-la-signature">Webhook</a>) ; ceux du produit vers M&#39;City portent le jeton de service.</li><li>M&#39;City ne suit pas les redirections : déclarez les URL définitives.</li></ul>',14)])])}const m=t(r,[["render",d]]);export{p as __pageData,m as default};
